import{_ as t,c as e,o as i,aj as s,b2 as r,b3 as l,b4 as a,b5 as n}from"./chunks/framework.C6C-pOXr.js";const b=JSON.parse('{"title":"iCloudBridge User Guide","description":"","frontmatter":{},"headers":[],"relativePath":"photos.md","filePath":"photos.md"}'),p={name:"photos.md"};function h(d,o,c,u,g,y){return i(),e("div",null,[...o[0]||(o[0]=[s('<h1 id="icloudbridge-user-guide" tabindex="-1">iCloudBridge User Guide <a class="header-anchor" href="#icloudbridge-user-guide" aria-label="Permalink to “iCloudBridge User Guide”">​</a></h1><p><a href="./user.html">&lt; Back to Table of Contents</a></p><h2 id="the-photos-page" tabindex="-1">The Photos Page <a class="header-anchor" href="#the-photos-page" aria-label="Permalink to “The Photos Page”">​</a></h2><p>The Photos page allows you to synchronise photos between Apple Photos and external services like Nextcloud. By default, iCloudBridge imports photos from external folders into Apple Photos. With bidirectional sync enabled, you can also export photos from Apple Photos to Nextcloud.</p><h3 id="how-it-works" tabindex="-1">How it Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to “How it Works”">​</a></h3><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Don&#39;t skip this part, it&#39;s important!</p></div><h4 id="one-way-sync-default-external-→-apple-photos" tabindex="-1">One-Way Sync (Default): External → Apple Photos <a class="header-anchor" href="#one-way-sync-default-external-→-apple-photos" aria-label="Permalink to “One-Way Sync (Default): External → Apple Photos”">​</a></h4><p>By default, iCloudBridge photo sync is one-way. It detects new photos in your external photos folder (for example Nextcloud) and imports them into your Apple Photos library. Here&#39;s how this works:</p><ol><li>Bob takes a photo on his iPhone. iCloud syncs this to his photo library, whilst the Nextcloud app on his phone syncs it to Nextcloud (using the Auto Upload feature).</li><li>When using his Android phone, Bob can see the photos he took on his iPhone using Nextcloud.</li><li>Bob takes a photo on his Android phone. The Nextcloud app on his phone syncs it to Nextcloud.</li><li><strong>This is where iCloudBridge comes in</strong>. iCloudBridge detects a new photo in Bob&#39;s Nextcloud library, and syncs it to his Apple Photos library.</li><li>When using his iPhone, Bob can now see the photos he took on his Android phone using the Apple Photos app.</li></ol><h4 id="bidirectional-sync-apple-photos-↔-nextcloud" tabindex="-1">Bidirectional Sync: Apple Photos ↔ Nextcloud <a class="header-anchor" href="#bidirectional-sync-apple-photos-↔-nextcloud" aria-label="Permalink to “Bidirectional Sync: Apple Photos ↔ Nextcloud”">​</a></h4><p>With bidirectional sync enabled, iCloudBridge can also export photos from Apple Photos to Nextcloud. This is useful when:</p><ul><li>You have a shared Apple Photos library with family members</li><li>Your spouse/partner takes photos on their iPhone that you want on Nextcloud</li><li>You want all your Apple Photos backed up to Nextcloud</li></ul><p><strong>Example scenario:</strong></p><ol><li>Alice and Bob share an Apple Photos library via iCloud Family Sharing</li><li>Alice takes a photo on her iPhone - it appears in the shared library</li><li>iCloudBridge exports Alice&#39;s photo to Nextcloud</li><li>Bob can now access Alice&#39;s photo on his Android phone via Nextcloud</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>Import limitation:</strong> Photos imported via iCloudBridge always go to your personal Apple Photos library. There is no way to programmatically import photos directly into a shared library - this is an Apple limitation. If you want imported photos in your shared library, you must manually move them after import.</p></div><h4 id="deduplication" tabindex="-1">Deduplication <a class="header-anchor" href="#deduplication" aria-label="Permalink to “Deduplication”">​</a></h4><p>iCloudBridge tracks the origin of every photo to prevent duplicates:</p><ul><li>Photos imported from Nextcloud won&#39;t be re-exported back to Nextcloud</li><li>Photos exported from Apple Photos won&#39;t be re-imported when they appear in Nextcloud</li></ul><p>As you can see, the photo sync functionality is designed to complement an existing one-way sync feature, such as that offered by Nextcloud. Whilst the focus is Nextcloud, nothing really stops you from using any other sync service, as long as your photos are stored in a folder on your Mac.</p><h3 id="syncing" tabindex="-1">Syncing <a class="header-anchor" href="#syncing" aria-label="Permalink to “Syncing”">​</a></h3><p>From the Photos page, click Simulate.</p><p><img src="'+r+'" alt="Photos scanning"></p><p>How long this takes depends on your Mac&#39;s speed and the size of your photo library. On my M1 Max with 15,000 photos, the scan takes roughly 90 seconds - so it&#39;s not too bad!</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>You may notice that the number of files scanned does not match the number of photos in your library. This is mostly due to live photos consisting of both a photo and a video.</p></div><p>After the simulation runs, you will be shown what would happen had you to sync:</p><p><img src="'+l+'" alt="Photos simulation result"></p><p>Here, I&#39;m shown that one new photo would be imported into Apple Photos.</p><p>If this makes sense, go ahead and click &quot;Sync&quot; to carry out the actual sync.</p><p><img src="'+a+'" alt="Photos sync result"></p><p>A new photo was imported into Apple Photos. You can verify this by checking your import album:</p><p><img src="'+n+'" alt="Photos sync result"></p><h3 id="exporting-bidirectional-sync" tabindex="-1">Exporting (Bidirectional Sync) <a class="header-anchor" href="#exporting-bidirectional-sync" aria-label="Permalink to “Exporting (Bidirectional Sync)”">​</a></h3><p>To enable photo export (Apple Photos → Nextcloud), you first need to configure it in the Settings page:</p><ol><li>Go to <strong>Settings</strong> → <strong>Photos</strong></li><li>Change <strong>Sync Mode</strong> from &quot;One-way&quot; to &quot;Bidirectional&quot;</li><li>Choose your <strong>Export Mode</strong>: <ul><li><strong>Going Forward</strong> (recommended): Only export photos added after enabling export</li><li><strong>Full Library</strong>: Export your entire Apple Photos library (use with caution for large libraries)</li></ul></li><li>Choose <strong>Folder Organization</strong>: <ul><li><strong>Date subfolders</strong> (recommended): Organizes exported photos by year/month (e.g., <code>2026/02/photo.jpg</code>)</li><li><strong>Flat</strong>: All photos exported to the folder root</li></ul></li><li>Click <strong>Save</strong></li></ol><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>Disable NextCloud Mobile Auto-Upload</strong></p><p>When using bidirectional sync, you must <strong>disable auto-upload</strong> of media from the NextCloud mobile app. Failing to do so will result in duplicate photos! iCloudBridge will handle exporting your Apple Photos to NextCloud - the mobile app&#39;s auto-upload is no longer needed.</p></div><p>The export folder is automatically set to the same folder as your import source. This creates a true bidirectional sync: photos flow in both directions through the same local folder, with NextCloud desktop app handling the cloud synchronization.</p><h4 id="using-bidirectional-sync" tabindex="-1">Using Bidirectional Sync <a class="header-anchor" href="#using-bidirectional-sync" aria-label="Permalink to “Using Bidirectional Sync”">​</a></h4><p>Once configured, the Photos page automatically adapts to bidirectional mode:</p><ul><li>The section title changes to <strong>&quot;Sync Photos&quot;</strong> (instead of &quot;Import Photos&quot;)</li><li>A <strong>&quot;Bidirectional&quot;</strong> badge appears in the status area</li><li>The <strong>Sync</strong> button now performs both import AND export in one operation</li></ul><p><strong>Available actions:</strong></p><ol><li><strong>Simulate</strong>: Preview what would be imported and exported without making any changes</li><li><strong>Sync</strong>: Perform the actual sync (imports from Nextcloud, then exports from Apple Photos)</li><li><strong>Set Baseline</strong>: Mark the current time as the baseline (only photos after this date will be exported in &quot;Going Forward&quot; mode)</li><li><strong>Full Library</strong>: Export your entire Apple Photos library (shows a warning for large libraries)</li></ol><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Always run &quot;Simulate&quot; first to preview the sync. The results show both import and export statistics separately.</p></div><h4 id="status-display" tabindex="-1">Status Display <a class="header-anchor" href="#status-display" aria-label="Permalink to “Status Display”">​</a></h4><p>In bidirectional mode, the status section shows both import and export statistics:</p><p><strong>Import stats:</strong></p><ul><li><strong>Library Items</strong>: Total photos tracked in source folders</li><li><strong>Pending</strong>: Photos waiting to be imported</li><li><strong>Skipped</strong>: Photos already in Apple Photos</li><li><strong>Last Imported</strong>: Photos imported in the most recent sync</li></ul><p><strong>Export stats:</strong></p><ul><li><strong>Total Exported</strong>: Number of photos exported so far</li><li><strong>Export Mode</strong>: Going Forward or Full Library</li><li><strong>Export Baseline</strong>: The date after which photos are eligible for export</li></ul><h4 id="sync-results" tabindex="-1">Sync Results <a class="header-anchor" href="#sync-results" aria-label="Permalink to “Sync Results”">​</a></h4><p>After running a sync (or simulation), the results panel shows statistics for both directions:</p><ul><li><strong>Import section</strong>: Discovered files, new assets, imported count, skipped count</li><li><strong>Export section</strong>: Exported count (or &quot;Would Export&quot; for simulations), skipped counts by reason</li></ul><h4 id="scheduled-syncs" tabindex="-1">Scheduled Syncs <a class="header-anchor" href="#scheduled-syncs" aria-label="Permalink to “Scheduled Syncs”">​</a></h4><p>When you add photos to a schedule, the scheduled sync will also respect the sync mode setting:</p><ul><li><strong>Import mode</strong>: Schedule only imports from folders</li><li><strong>Bidirectional mode</strong>: Schedule imports then exports</li><li><strong>Export mode</strong>: Schedule only exports from Apple Photos</li></ul><hr><p><a href="./passwords.html">&lt; Previous - Password Synchronisation</a> | <a href="./schedules.html">Next - Schedules &gt;</a></p>',56)])])}const f=t(p,[["render",h]]);export{b as __pageData,f as default};
